// ---------------------------------------------------------------------------
// Evaluation
// ---------------------------------------------------------------------------

/// Runs a node.
///
/// Implemented for every generated AST type, so a `lazy` parameter is
/// run with `.eval(host, cx)?` at whatever moment the handler chooses —
/// including never, or more than once.
pub trait Eval {
    fn eval<H: Handlers>(&self, host: &mut H, cx: &mut Ctx) -> Result<H::Out>;
}

/// Evaluates `program`, from `SOI EOL* lazy lines:line* EOI -> doc`.
pub fn eval_program<H: Handlers>(host: &mut H, node: &Program, cx: &mut Ctx) -> Result<H::Out> {
    // Entering the node's span is what makes `cx.err(..)` inside the
    // handler locate itself with no span bookkeeping (DESIGN.md §7).
    cx.enter(node.span);
    let result = eval_program_inner(host, node, cx);
    cx.leave();
    result
}

fn eval_program_inner<H: Handlers>(
    host: &mut H,
    node: &Program,
    cx: &mut Ctx,
) -> Result<H::Out> {
    let lines = &node.lines;
    host.program(lines, cx)
}

impl Eval for Program {
    fn eval<H: Handlers>(&self, host: &mut H, cx: &mut Ctx) -> Result<H::Out> {
        eval_program(host, self, cx)
    }
}

/// Evaluates `line`, from `label:NUMBER? body:stmt EOL* -> line`.
pub fn eval_line<H: Handlers>(host: &mut H, node: &Line, cx: &mut Ctx) -> Result<H::Out> {
    // Entering the node's span is what makes `cx.err(..)` inside the
    // handler locate itself with no span bookkeeping (DESIGN.md §7).
    cx.enter(node.span);
    let result = eval_line_inner(host, node, cx);
    cx.leave();
    result
}

fn eval_line_inner<H: Handlers>(
    host: &mut H,
    node: &Line,
    cx: &mut Ctx,
) -> Result<H::Out> {
    let label = node.label.as_deref();
    let body = eval_stmt(host, &node.body, cx)?;
    host.line(label, body, cx)
}

impl Eval for Line {
    fn eval<H: Handlers>(&self, host: &mut H, cx: &mut Ctx) -> Result<H::Out> {
        eval_line(host, self, cx)
    }
}

/// Evaluates a `stmt` by handing off to whichever alternative matched.
pub fn eval_stmt<H: Handlers>(host: &mut H, node: &Stmt, cx: &mut Ctx) -> Result<H::Out> {
    match node {
        Stmt::Loop(n) => eval_stmt_loop(host, n, cx),
        Stmt::While(n) => eval_stmt_while(host, n, cx),
        Stmt::Define(n) => eval_stmt_define(host, n, cx),
        Stmt::Call(n) => eval_stmt_call(host, n, cx),
        Stmt::Function(n) => eval_stmt_function(host, n, cx),
        Stmt::Ret(n) => eval_stmt_ret(host, n, cx),
        Stmt::Goto(n) => eval_stmt_goto(host, n, cx),
        Stmt::ExitFor(n) => eval_stmt_exit_for(host, n, cx),
        Stmt::ExitWhile(n) => eval_stmt_exit_while(host, n, cx),
        Stmt::ExitSub(n) => eval_stmt_exit_sub(host, n, cx),
        Stmt::ContinueFor(n) => eval_stmt_continue_for(host, n, cx),
        Stmt::ContinueWhile(n) => eval_stmt_continue_while(host, n, cx),
        Stmt::Iff(n) => eval_stmt_iff(host, n, cx),
        Stmt::Print(n) => eval_stmt_print(host, n, cx),
        Stmt::Blank(n) => eval_stmt_blank(host, n, cx),
        Stmt::Let(n) => eval_stmt_let(host, n, cx),
    }
}

impl Eval for Stmt {
    fn eval<H: Handlers>(&self, host: &mut H, cx: &mut Ctx) -> Result<H::Out> {
        eval_stmt(host, self, cx)
    }
}

/// Evaluates `stmt`, from `"FOR" var:IDENT "=" from:expr "TO" to:expr step:step_clause? EOL* lazy body:line* "NEXT" closing:IDENT? -> loop`.
